prompt --application/shared_components/plugins/region_type/com_flowchat_designer
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(481516234200001)
,p_plugin_type=>'REGION TYPE'
,p_name=>'COM.FLOWCHAT.DESIGNER'
,p_display_name=>'FlowChat Designer'
,p_supported_component_types=>'APEX_APPLICATION_PAGE_REGIONS'
,p_css_file_urls=>wwv_flow_string.join(wwv_flow_t_varchar2(
'#PLUGIN_FILES#designer.css'))
,p_javascript_file_urls=>wwv_flow_string.join(wwv_flow_t_varchar2(
'#PLUGIN_FILES#flowchat-engine.js',
'#PLUGIN_FILES#flowchat.js',
'#PLUGIN_FILES#designer.js'))
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- FlowChat Designer region plugin. Needs FC_DESIGNER (db/09_fc_designer.sql) in the parsing schema.',
'function render (',
'  p_region              in apex_plugin.t_region,',
'  p_plugin              in apex_plugin.t_plugin,',
'  p_is_printer_friendly in boolean )',
'  return apex_plugin.t_region_render_result',
'is',
'  l_height varchar2(200) := nvl(trim(p_region.attribute_01), ''calc(100vh - 140px)'');',
'  l_theme  varchar2(10)  := nvl(p_region.attribute_02, ''auto'');',
'  l_mode   varchar2(10)  := nvl(p_region.attribute_03, ''database'');',
'  l_result apex_plugin.t_region_render_result;',
'begin',
'  if apex_application.g_debug then',
'    apex_plugin_util.debug_region(p_plugin => p_plugin, p_region => p_region);',
'  end if;',
'  -- a CSS length only, so the value cannot leave the style attribute',
'  if not regexp_like(l_height, ''^[-a-zA-Z0-9.%() +*]{1,100}$'') then',
'    l_height := ''calc(100vh - 140px)'';',
'  end if;',
'  sys.htp.p(''<div id="fcd-root"''',
'    || case when l_mode = ''database''',
'            then '' data-backend="apex" data-ajax-identifier="'' || apex_escape.html_attribute(apex_plugin.get_ajax_identifier) || ''"''',
'            else '' data-backend="files"'' end',
'    || '' data-flows-base="'' || apex_escape.html_attribute(p_plugin.file_prefix) || ''"''',
'    || case when l_theme in (''light'', ''dark'') then '' data-theme="'' || l_theme || ''"'' end',
'    || '' style="--fcd-height: '' || l_height || ''"></div>'');',
'  return l_result;',
'end render;',
'',
'function ajax (',
'  p_region in apex_plugin.t_region,',
'  p_plugin in apex_plugin.t_plugin )',
'  return apex_plugin.t_region_ajax_result',
'is',
'  l_result apex_plugin.t_region_ajax_result;',
'begin',
'  if nvl(p_region.attribute_03, ''database'') <> ''database'' then',
'    sys.htp.p(''{"error":"This designer region works on files only (Mode = Files)."}'');',
'    return l_result;',
'  end if;',
'  fc_designer.ajax;',
'  return l_result;',
'end ajax;'))
,p_api_version=>2
,p_render_function=>'render'
,p_ajax_function=>'ajax'
,p_substitute_attributes=>true
,p_subscribe_plugin_settings=>true
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Hosts the FlowChat flow designer. In Database mode it opens, saves and publishes flows in FC_FLOW_VERSIONS',
'and edits the data source, lookup list and AI registries through FC_DESIGNER, using this region''s own AJAX',
'callback (no page process needed). Anyone who can open the page can publish flows: protect the page or the',
'region with an authorization scheme. Use one designer region per page.'))
,p_version_identifier=>'1.1.0'
,p_files_version=>1
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(481516234200011)
,p_plugin_id=>wwv_flow_imp.id(481516234200001)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_prompt=>'Height'
,p_attribute_type=>'TEXT'
,p_is_required=>false
,p_default_value=>'calc(100vh - 140px)'
,p_is_translatable=>false
,p_help_text=>'Height of the designer, as a CSS length: e.g. calc(100vh - 140px), 800px or 90vh.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(481516234200012)
,p_plugin_id=>wwv_flow_imp.id(481516234200001)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>2
,p_display_sequence=>20
,p_prompt=>'Theme'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'auto'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>'Colours of the designer. Automatic follows the browser (light or dark).'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(481516234200120)
,p_plugin_attribute_id=>wwv_flow_imp.id(481516234200012)
,p_display_sequence=>10
,p_display_value=>'Automatic'
,p_return_value=>'auto'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(481516234200121)
,p_plugin_attribute_id=>wwv_flow_imp.id(481516234200012)
,p_display_sequence=>20
,p_display_value=>'Light'
,p_return_value=>'light'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(481516234200122)
,p_plugin_attribute_id=>wwv_flow_imp.id(481516234200012)
,p_display_sequence=>30
,p_display_value=>'Dark'
,p_return_value=>'dark'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(481516234200013)
,p_plugin_id=>wwv_flow_imp.id(481516234200001)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>3
,p_display_sequence=>30
,p_prompt=>'Mode'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'database'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>'Database: open, save and publish flows in the database (needs FC_DESIGNER). Files: work on JSON files only, like the standalone designer.'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(481516234200130)
,p_plugin_attribute_id=>wwv_flow_imp.id(481516234200013)
,p_display_sequence=>10
,p_display_value=>'Database'
,p_return_value=>'database'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(481516234200131)
,p_plugin_attribute_id=>wwv_flow_imp.id(481516234200013)
,p_display_sequence=>20
,p_display_value=>'Files'
,p_return_value=>'files'
);
end;
